//! Unicode character properties for the terminal core: cell width, grapheme cluster breaks (UAX 29) and cluster
//! width (UTS 51). The data in `tables.rs` is generated by `tools/unicode-tables` from the files in
//! `corpus/unicode/17.0.0/`.
//!
//! Deliberate differences from the `unicode-width` crate: Hangul medial vowels and final consonants
//! (U+1160..U+11FF, U+D7B0..U+D7FF) are width 0, regional indicators are width 1 alone (a pair is width 2
//! through `cluster_width`), and the C0, DEL and C1 controls are width 0.

mod tables;

/// The Unicode version the tables were generated from.
pub const UNICODE_VERSION: (u8, u8, u8) = (17, 0, 0);

/// The Unicode version text of the data the tables were generated from, for consistency checks.
pub const TABLES_DATA_VERSION: &str = tables::DATA_VERSION;

/// Grapheme_Cluster_Break property values.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum GraphemeBreak {
    Other,
    CR,
    LF,
    Control,
    Extend,
    ZWJ,
    RegionalIndicator,
    Prepend,
    SpacingMark,
    L,
    V,
    T,
    LV,
    LVT,
}

/// Indic_Conjunct_Break property values, needed for rule GB9c.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum IndicConjunctBreak {
    None,
    Linker,
    Consonant,
    Extend,
}

/// Every property of one code point that the terminal needs.
#[derive(Clone, Copy, Debug)]
pub struct CharProps {
    /// Legacy per code point terminal width: 0, 1 or 2.
    pub width: u8,
    pub grapheme: GraphemeBreak,
    pub incb: IndicConjunctBreak,
    pub extended_pictographic: bool,
    pub emoji_presentation: bool,
}

const GRAPHEME_VALUES: [GraphemeBreak; 14] = [
    GraphemeBreak::Other,
    GraphemeBreak::CR,
    GraphemeBreak::LF,
    GraphemeBreak::Control,
    GraphemeBreak::Extend,
    GraphemeBreak::ZWJ,
    GraphemeBreak::RegionalIndicator,
    GraphemeBreak::Prepend,
    GraphemeBreak::SpacingMark,
    GraphemeBreak::L,
    GraphemeBreak::V,
    GraphemeBreak::T,
    GraphemeBreak::LV,
    GraphemeBreak::LVT,
];
const INCB_VALUES: [IndicConjunctBreak; 4] =
    [IndicConjunctBreak::None, IndicConjunctBreak::Linker, IndicConjunctBreak::Consonant, IndicConjunctBreak::Extend];

/// Decodes a packed table value (see the header of `tables.rs`) into a `CharProps`.
fn unpack(packed: u16) -> CharProps {
    CharProps {
        width: (packed & 3) as u8,
        grapheme: GRAPHEME_VALUES[((packed >> 2) & 15) as usize],
        incb: INCB_VALUES[((packed >> 6) & 3) as usize],
        extended_pictographic: packed & (1 << 8) != 0,
        emoji_presentation: packed & (1 << 9) != 0,
    }
}

/// Looks up the packed value of a code point through the three stage table.
#[inline]
fn lookup_packed(c: char) -> u16 {
    let cp = c as usize;
    if cp < 0x80 {
        return tables::ASCII[cp];
    }
    let block = tables::STAGE1[cp >> tables::BLOCK_SHIFT] as usize;
    let index = tables::STAGE2[(block << tables::BLOCK_SHIFT) | (cp & ((1 << tables::BLOCK_SHIFT) - 1))];
    tables::VALUES[index as usize]
}

/// The packed property word of a code point (width in bits 0 and 1, then the grapheme break, the
/// conjunct break and the emoji flags). A word with nothing above bit 1 set is a plain character:
/// it has no grapheme break class other than Other, so it never joins the cluster before it
/// (unless that ended in a Prepend character) and always leaves the breaker in
/// [`GraphemeBreaker::PLAIN`].
#[inline]
pub fn packed_props(c: char) -> u16 {
    lookup_packed(c)
}

/// Returns all properties of a code point with a constant number of table reads.
pub fn props(c: char) -> CharProps {
    unpack(lookup_packed(c))
}

/// Returns the legacy terminal width (0, 1 or 2) of a single code point.
pub fn char_width(c: char) -> u8 {
    let cp = c as u32;
    if cp < 0x80 {
        return u8::from(cp >= 0x20 && cp != 0x7F);
    }
    (lookup_packed(c) & 3) as u8
}

/// State of the GB11 emoji sequence rule: Extended_Pictographic Extend* ZWJ.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum EmojiState {
    None,
    Pictographic,
    AfterJoiner,
}

/// State of the GB9c conjunct rule: Consonant [Extend Linker]* Linker [Extend Linker]*.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ConjunctState {
    None,
    Consonant,
    Linked,
}

/// Stateful extended grapheme cluster breaker implementing UAX 29 rules GB3 to GB13 and GB999.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct GraphemeBreaker {
    prev: GraphemeBreak,
    regional_odd: bool,
    emoji: EmojiState,
    conjunct: ConjunctState,
}

impl GraphemeBreaker {
    /// The state after a plain character (see [`packed_props`]): the previous class is Other and
    /// no emoji, conjunct or regional indicator sequence is open.
    pub const PLAIN: GraphemeBreaker = GraphemeBreaker {
        prev: GraphemeBreak::Other,
        regional_odd: false,
        emoji: EmojiState::None,
        conjunct: ConjunctState::None,
    };

    /// Starts a cluster whose first code point is `first`.
    pub fn new(first: char) -> Self {
        let mut breaker = GraphemeBreaker {
            prev: GraphemeBreak::Control,
            regional_odd: false,
            emoji: EmojiState::None,
            conjunct: ConjunctState::None,
        };
        breaker.advance(props(first), true);
        breaker
    }

    /// Starts a cluster from properties the caller already looked up.
    pub fn from_props(first: CharProps) -> Self {
        let mut breaker = GraphemeBreaker {
            prev: GraphemeBreak::Control,
            regional_odd: false,
            emoji: EmojiState::None,
            conjunct: ConjunctState::None,
        };
        breaker.advance(first, true);
        breaker
    }

    /// True when the last code point was a Prepend character, after which even an ASCII character
    /// joins the cluster (GB9b). No other rule joins ASCII to what came before.
    #[inline]
    pub fn joins_ascii(&self) -> bool {
        self.prev == GraphemeBreak::Prepend
    }

    /// Returns true when a cluster boundary falls before `next`, and records `next` as the latest code point.
    pub fn should_break(&mut self, next: char) -> bool {
        let p = props(next);
        let split = self.boundary_before(&p);
        self.advance(p, split);
        split
    }

    /// [`GraphemeBreaker::should_break`] for a code point whose properties the caller already
    /// looked up, so a code point that is also measured is looked up once.
    pub fn should_break_props(&mut self, p: &CharProps) -> bool {
        let split = self.boundary_before(p);
        self.advance(*p, split);
        split
    }

    /// Applies the break rules in order to decide whether a boundary falls between the previous code point and `p`.
    fn boundary_before(&self, p: &CharProps) -> bool {
        use GraphemeBreak::*;
        let (prev, next) = (self.prev, p.grapheme);
        match (prev, next) {
            (CR, LF) => return false,
            (Control | CR | LF, _) | (_, Control | CR | LF) => return true,
            (L, L | V | LV | LVT) | (LV | V, V | T) | (LVT | T, T) => return false,
            (_, Extend | ZWJ | SpacingMark) | (Prepend, _) => return false,
            _ => {}
        }
        if p.incb == IndicConjunctBreak::Consonant && self.conjunct == ConjunctState::Linked {
            return false;
        }
        if p.extended_pictographic && self.emoji == EmojiState::AfterJoiner {
            return false;
        }
        !(prev == RegionalIndicator && next == RegionalIndicator && self.regional_odd)
    }

    /// Updates the remembered context after `p` was appended; `split` says a boundary fell before it.
    fn advance(&mut self, p: CharProps, split: bool) {
        self.regional_odd = p.grapheme == GraphemeBreak::RegionalIndicator && (split || !self.regional_odd);
        self.emoji = next_emoji_state(self.emoji, &p);
        self.conjunct = next_conjunct_state(self.conjunct, &p);
        self.prev = p.grapheme;
    }
}

/// Moves the GB11 state machine over one code point.
fn next_emoji_state(state: EmojiState, p: &CharProps) -> EmojiState {
    if p.extended_pictographic {
        return EmojiState::Pictographic;
    }
    match (state, p.grapheme) {
        (EmojiState::Pictographic, GraphemeBreak::Extend) => EmojiState::Pictographic,
        (EmojiState::Pictographic, GraphemeBreak::ZWJ) => EmojiState::AfterJoiner,
        _ => EmojiState::None,
    }
}

/// Moves the GB9c state machine over one code point.
fn next_conjunct_state(state: ConjunctState, p: &CharProps) -> ConjunctState {
    match (p.incb, state) {
        (IndicConjunctBreak::Consonant, _) => ConjunctState::Consonant,
        (IndicConjunctBreak::Linker, ConjunctState::None) => ConjunctState::None,
        (IndicConjunctBreak::Linker, _) => ConjunctState::Linked,
        (IndicConjunctBreak::Extend, s) => s,
        (IndicConjunctBreak::None, _) => ConjunctState::None,
    }
}

const VS15: char = '\u{FE0E}';
const VS16: char = '\u{FE0F}';
const ZWJ: char = '\u{200D}';
const KEYCAP: char = '\u{20E3}';

/// True for the five emoji skin tone modifiers.
fn is_skin_tone(c: char) -> bool {
    ('\u{1F3FB}'..='\u{1F3FF}').contains(&c)
}

/// True for the characters that can start a keycap sequence: digits, number sign and asterisk.
fn is_keycap_base(c: char) -> bool {
    c.is_ascii_digit() || c == '#' || c == '*'
}

/// Width in cells (1 or 2) of a whole grapheme cluster under mode 2027, following UTS 51. A zero width first
/// code point still takes one cell. An empty cluster has width 0.
pub fn cluster_width(cluster: &[char]) -> u8 {
    match cluster.split_first() {
        Some((&first, rest)) => cluster_width_parts(first, rest),
        None => 0,
    }
}

/// [`cluster_width`] for a cluster given as its first code point and the code points after it, so
/// a caller that keeps the tail apart from the first code point does not have to join them.
pub fn cluster_width_parts(first: char, rest: &[char]) -> u8 {
    let p = props(first);
    if rest.is_empty() {
        return p.width.max(1);
    }
    if p.grapheme == GraphemeBreak::RegionalIndicator {
        return if props(rest[0]).grapheme == GraphemeBreak::RegionalIndicator { 2 } else { 1 };
    }
    emoji_sequence_width(first, &p, rest).unwrap_or(p.width.max(1))
}

/// Applies the emoji sequence rules to a cluster of two or more code points; None when no rule applies.
fn emoji_sequence_width(first: char, p: &CharProps, rest: &[char]) -> Option<u8> {
    let has = |target: char| rest.contains(&target);
    if is_keycap_base(first) && has(VS16) && has(KEYCAP) {
        return Some(2);
    }
    if !(p.extended_pictographic || p.emoji_presentation) {
        return None;
    }
    if has(VS15) && !has(VS16) {
        return Some(1);
    }
    let widened = has(VS16) || has(ZWJ) || rest.iter().any(|&c| is_skin_tone(c));
    if widened && p.extended_pictographic { Some(2) } else { None }
}
